using System.Text; using System.Text.Json.Serialization; using Microsoft.AspNetCore.RateLimiting; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using Microsoft.OpenApi.Models; using OpenDentalFlow.Api.Data; using OpenDentalFlow.Api.Domain; using OpenDentalFlow.Api.Services;
var b=WebApplication.CreateBuilder(args);b.WebHost.UseUrls(b.Configuration["Urls"]??"http://0.0.0.0:5080");b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("Default")));b.Services.AddScoped<IShortCodeService,ShortCodeService>();b.Services.AddSingleton<ICodeService,CodeService>();b.Services.AddSingleton<ILabelService,LabelService>();b.Services.AddScoped<IFileStorage,LocalFileStorage>();b.Services.AddControllers().AddJsonOptions(o=>o.JsonSerializerOptions.ReferenceHandler=ReferenceHandler.IgnoreCycles);b.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));var key=Encoding.UTF8.GetBytes(b.Configuration["Jwt:Key"]!);b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(key)});b.Services.AddAuthorization();b.Services.AddRateLimiter(o=>o.AddFixedWindowLimiter("public",x=>{x.PermitLimit=60;x.Window=TimeSpan.FromMinutes(1);x.QueueLimit=0;}));b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen(c=>{c.SwaggerDoc("v1",new(){Title="OpenDentalFlow API",Version="v1"});c.AddSecurityDefinition("Bearer",new(){Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT"});});
var app=b.Build();app.UseSwagger();app.UseSwaggerUI();app.UseCors();app.UseRateLimiter();app.UseStaticFiles(new StaticFileOptions{FileProvider=new Microsoft.Extensions.FileProviders.PhysicalFileProvider(Path.Combine(app.Environment.ContentRootPath,"uploads")),RequestPath="/uploads"});app.UseAuthentication();app.UseAuthorization();app.MapControllers();
using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>();await db.Database.MigrateAsync();if(!await db.Users.AnyAsync()){db.Users.Add(new(){Username="admin",PasswordHash=BCrypt.Net.BCrypt.HashPassword("Admin123!"),Role=UserRole.Admin});var c=new Clinic{Name="DentPlus",ShortCode="DPL",Phone="0212 555 01 01",LastPatientSequence=1};var p=new Patient{Clinic=c,PatientCode="DPL-001",ClinicSequence=1,FirstName="Örnek",LastName="Hasta"};var j=new Job{Clinic=c,Patient=p,JobCode="DPL-001-1",JobSequence=1,JobType="Zirkonyum Kron",Material="Zirkonyum",Shade="A2",Teeth="11,12",UnitCount=2,DueDate=DateTime.Today.AddDays(3),AccessToken=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(10))};db.AddRange(c,p,j,new SystemSetting{Key="PublicBaseUrl",Value=b.Configuration["PublicBaseUrl"]!});await db.SaveChangesAsync();}}app.Run();public partial class Program{}
